const input = $input.first().json;
const payload = (input.body && typeof input.body === 'object') ? input.body : input;
const query = String(payload.query || payload.search_query || '').trim();
if (!query) {
  throw new Error('query is required');
}
const maxResults = Number(payload.max_results || 5);
const apifyToken = String(
  payload.apify_token
  || payload.apify_api_token
  || payload.token
  || ''
).trim();
if (!apifyToken) {
  throw new Error('apify_token or apify_api_token is required');
}
return [{ json: {
  query,
  max_results: Number.isFinite(maxResults) && maxResults > 0 ? Math.min(maxResults, 10) : 5,
  actor_id: String(payload.actor_id || 'apify/google-search-scraper').trim(),
  apify_token: apifyToken
} }];

const request = $('Prepare Search Request').first().json;
const payload = $input.first().json;
const organicResults = Array.isArray(payload.organicResults) ? payload.organicResults : [];
const fallbackResults = Array.isArray(payload.relatedQueries) ? payload.relatedQueries : [];
const rows = organicResults.length > 0 ? organicResults : fallbackResults;
const sources = rows.slice(0, request.max_results).map((row, index) => ({
  title: String(row.title || row.pageTitle || row.name || '').trim(),
  url: String(row.url || row.link || row.pageUrl || '').trim(),
  snippet: String(row.description || row.snippet || row.text || '').trim(),
  rank: Number(row.position || index + 1)
})).filter((row) => row.url);
return [{ json: {
  query: request.query,
  source_count: sources.length,
  sources
} }];
